function exactlyKKinds(nums: number[], k: number): number {
  const atMost = (m: number): number => {
    const count = new Map<number, number>();
    let left = 0, total = 0;
    for (let right = 0; right < nums.length; right++) {
      count.set(nums[right], (count.get(nums[right]) ?? 0) + 1);
      while (count.size > m) {
        const v = nums[left++], c = count.get(v)! - 1;
        if (c === 0) count.delete(v); else count.set(v, c);
      }
      total += right - left + 1;
    }
    return total;
  };
  return atMost(k) - atMost(k - 1);
}

